-- 25개 도시의 상세 설명(description) 업데이트
UPDATE destinations SET description = '한국에서 가장 가까운 일본 도시 중 하나인 후쿠오카는 가볍게 다녀오기 좋은 여행지예요. 하카타 라멘, 모츠나베 같은 먹거리가 풍부하고, 텐진과 캐널시티 같은 쇼핑 거리도 잘 갖춰져 있어요. 오호리 공원이나 모모치 해변처럼 여유롭게 산책하기 좋은 장소도 많아서, 짧은 일정에도 일본 여행 분위기를 충분히 느낄 수 있는 도시예요.' WHERE name = '후쿠오카';
UPDATE destinations SET description = '일본을 대표하는 미식 도시 오사카는 먹고 즐기는 여행에 잘 어울리는 곳이에요. 도톤보리의 화려한 거리와 타코야키, 오코노미야키 같은 길거리 음식이 특히 유명해요. 유니버설 스튜디오 재팬도 있어서 하루를 온전히 놀이공원에서 보내기 좋아요. 활기찬 분위기 덕분에 처음 가는 일본 여행지로도 많이 선택되는 도시예요.' WHERE name = '오사카';
UPDATE destinations SET description = '도쿄는 전통과 현대가 함께 어우러진 일본의 수도예요. 시부야와 신주쿠의 화려한 거리부터 아사쿠사의 오래된 사원까지, 다양한 분위기의 장소를 한 번에 만날 수 있어요. 쇼핑, 전시, 미식, 테마파크까지 여행 요소가 풍부해서 취향에 따라 일정을 다양하게 만들 수 있는 도시예요.' WHERE name = '도쿄';
UPDATE destinations SET description = '세부는 필리핀을 대표하는 휴양지 중 하나로, 바다와 리조트 휴식을 함께 즐기기 좋은 곳이에요. 맑은 바다에서 스노클링이나 호핑투어를 즐기고, 리조트에서 여유로운 시간을 보내기 좋아요. 특히 건기(12월~5월)에는 바다 색이 더욱 선명해져서 해양 액티비티를 즐기기에 좋은 시기예요.' WHERE name = '세부';
UPDATE destinations SET description = '화이트 비치로 유명한 보라카이, 필리핀을 대표하는 휴양지예요. 에메랄드빛 바다와 고운 모래사장이 펼쳐져 있어서 휴식에 집중하고 싶을 때 특히 잘 어울리는 곳이에요. 특히 건기(11월~5월)에는 하늘이 맑고 파도도 잔잔해서 보라카이 특유의 투명한 물빛을 더 또렷하게 만날 수 있어요.' WHERE name = '보라카이';
UPDATE destinations SET description = '초콜릿 힐과 고요한 자연 풍경으로 유명한 보홀은 한적하게 여행하기 좋은 필리핀 섬이에요. 에메랄드빛 바다에서 스노클링을 즐기고, 로복 강에서 여유로운 리버 크루즈를 경험할 수 있어요. 자연을 가까이에서 느끼며 조용한 휴식을 보내고 싶을 때 특히 잘 어울리는 여행지예요.' WHERE name = '보홀';
UPDATE destinations SET description = '상하이는 중국에서 가장 현대적인 도시 중 하나로, 화려한 야경과 도시 풍경이 인상적인 곳이에요. 와이탄에서 바라보는 스카이라인은 특히 유명하고, 유럽풍 건물과 현대적인 마천루가 함께 어우러져 독특한 분위기를 만들어요. 쇼핑과 미식, 도시 산책을 즐기기에 좋은 여행지예요.' WHERE name = '상하이';
UPDATE destinations SET description = '중국의 수도 베이징은 역사와 문화 유산이 풍부한 도시예요. 자금성과 만리장성처럼 세계적으로 유명한 유적지를 가까이에서 볼 수 있어요. 오래된 골목인 후통을 걸으며 전통적인 중국 분위기를 느껴보는 것도 특별한 경험이에요.' WHERE name = '베이징';
UPDATE destinations SET description = '바다와 유럽풍 건축이 어우러진 칭다오는 중국에서 색다른 분위기를 가진 도시예요. 해안 산책로를 따라 걸으며 바다 풍경을 즐기기 좋고, 칭다오 맥주로 유명한 맥주 거리도 활기찬 분위기를 느낄 수 있는 곳이에요. 여유로운 바다 도시 여행을 즐기기 좋은 곳이에요.' WHERE name = '칭다오';
UPDATE destinations SET description = '가우디 건축과 지중해 바다가 어우러진 바르셀로나는 스페인을 대표하는 여행 도시예요. 사그라다 파밀리아와 구엘 공원처럼 독특한 건축 작품을 가까이에서 볼 수 있어요. 바르셀로네타 해변에서 여유로운 시간을 보내며 도시와 휴양을 함께 즐길 수 있는 곳이에요.' WHERE name = '바르셀로나';
UPDATE destinations SET description = '마드리드는 스페인의 수도로, 예술과 미식 문화가 살아 있는 도시예요. 프라도 미술관과 레티로 공원 같은 명소가 있고, 광장을 중심으로 활기찬 도시 분위기가 이어져요. 타파스를 맛보며 천천히 도시를 즐기기 좋은 여행지예요.' WHERE name = '마드리드';
UPDATE destinations SET description = '로스앤젤레스는 영화와 해변 문화로 유명한 미국의 대표적인 도시예요. 할리우드 거리와 산타모니카 해변, 베니스 비치 등 다양한 명소가 있어요. 도시와 휴양 분위기를 동시에 느낄 수 있는 여행지예요.' WHERE name = 'LA';
UPDATE destinations SET description = '뉴욕은 세계적인 문화와 예술의 중심지로, 언제 가도 활기찬 에너지를 느낄 수 있는 도시예요. 센트럴파크와 타임스퀘어, 브로드웨이 공연까지 다양한 경험이 가능해요. 도시 여행의 매력을 제대로 느끼고 싶다면 꼭 한 번 가볼 만한 곳이에요.' WHERE name = '뉴욕';
UPDATE destinations SET description = '샌프란시스코는 언덕 위 도시 풍경과 골든게이트 브리지로 유명한 곳이에요. 케이블카를 타고 도시를 천천히 둘러보는 것도 특별한 경험이에요. 바다와 도시 풍경이 어우러져 독특한 분위기를 느낄 수 있는 여행지예요.' WHERE name = '샌프란시스코';
UPDATE destinations SET description = '다낭은 베트남 중부에 위치한 휴양 도시로, 바다와 관광을 함께 즐기기 좋은 곳이에요. 미케 비치에서 여유로운 시간을 보내고, 바나힐과 호이안 같은 근교 명소도 함께 방문하기 좋아요. 짧은 일정에도 알찬 여행을 만들 수 있는 곳이에요.' WHERE name = '다낭';
UPDATE destinations SET description = '호치민은 베트남의 경제 중심 도시로, 활기찬 분위기와 다양한 먹거리가 가득한 곳이에요. 카페 문화가 발달해 있어서 골목마다 개성 있는 카페를 발견하는 재미가 있어요. 베트남의 도시 문화를 가까이에서 느껴볼 수 있는 여행지예요.' WHERE name = '호치민';
UPDATE destinations SET description = '브리즈번은 호주의 따뜻한 기후와 여유로운 분위기를 느낄 수 있는 도시예요. 브리즈번 강을 따라 산책하거나 근교 자연을 여행하기 좋아요. 골드코스트와도 가까워서 함께 여행하기 좋은 곳이에요.' WHERE name = '브리즈번';
UPDATE destinations SET description = '시드니는 오페라하우스와 하버 브리지로 유명한 호주의 대표 도시예요. 아름다운 항구 풍경과 본다이 비치 같은 해변이 있어 도시와 자연을 함께 즐길 수 있어요. 여유로운 분위기 속에서 다양한 여행 경험을 할 수 있는 곳이에요.' WHERE name = '시드니';
UPDATE destinations SET description = '멜버른은 호주의 문화와 예술 중심지로, 감각적인 카페와 골목 예술이 유명한 도시예요. 도시 곳곳에 갤러리와 공연장이 있어서 문화적인 분위기를 느끼기 좋아요. 여유로운 도시 여행을 즐기기 좋은 곳이에요.' WHERE name = '멜버른';
UPDATE destinations SET description = '파리는 예술과 낭만의 도시로 불리는 프랑스의 수도예요. 에펠탑과 루브르 박물관 같은 세계적인 명소가 있고, 세느강을 따라 걷는 것만으로도 특별한 분위기를 느낄 수 있어요. 천천히 산책하며 도시의 매력을 발견하기 좋은 곳이에요.' WHERE name = '파리';
UPDATE destinations SET description = '니스는 프랑스 남부 지중해 연안에 위치한 휴양 도시예요. 푸른 바다와 햇살이 어우러진 해안 풍경이 특히 아름다워요. 해변 산책로인 프롬나드 데 장글레를 따라 걸으며 여유로운 시간을 보내기 좋은 곳이에요.' WHERE name = '니스';
UPDATE destinations SET description = '삿포로는 홋카이도의 중심 도시로, 계절마다 다른 매력을 보여주는 곳이에요. 여름에는 시원한 날씨 덕분에 산책하기 좋고, 겨울에는 눈이 도시를 덮어 특별한 풍경을 만들어줘요. 자연과 도시 분위기를 함께 느낄 수 있는 여행지예요.' WHERE name = '삿포로';
UPDATE destinations SET description = '서울은 전통과 현대가 공존하는 한국의 수도예요. 경복궁 같은 역사 유적부터 홍대와 성수 같은 트렌디한 거리까지 다양한 분위기를 한 도시에서 만날 수 있어요. 맛집과 쇼핑, 문화 공간이 풍부해 언제 방문해도 즐길 거리가 많은 도시예요.' WHERE name = '서울';
UPDATE destinations SET description = '부산은 바다와 도시 풍경이 함께 어우러진 한국의 대표적인 항구 도시예요. 해운대와 광안리 해변에서 바다를 즐기고, 감천문화마을이나 자갈치시장 같은 곳에서 부산만의 분위기를 느낄 수 있어요. 활기찬 바다 도시 여행을 즐기기 좋은 곳이에요.' WHERE name = '부산';
UPDATE destinations SET description = '제주도는 한국을 대표하는 자연 여행지로, 화산 지형과 푸른 바다가 함께 어우러진 섬이에요. 한라산과 오름, 해안 도로를 따라 다양한 풍경을 만날 수 있어요. 여유롭게 드라이브하며 자연을 즐기기 좋은 여행지예요.' WHERE name = '제주도';
